-- 097 VERIFY - GENERATED by worker/migrations/drafts/tools/build-097.mjs from 097_plan_vs_state_hub_only.sql. Read only (SELECT), one row.
-- DO NOT EDIT BY HAND (the md5 below is the migration's own; tests/sql-097-drafts.test.js fails on drift).
-- EXPECTED right after 097: applied = '097 in place', vs_legs_off_veroia 0, vs_carried_no_veroia_day 0, b54_matches true.
--   After 098 is in use: vs_legs_off_veroia = one per VS transfer - the leg whose Veroia-side stop is the transfer
--   point (an import's leg that LOADS there, an export's leg that UNLOADS there; the other leg of that transfer touches
--   Veroia and is not counted); vs_carried_no_veroia_day = VS orders on a truck that has not reached Veroia yet (an
--   export waiting at a transfer point) - their international keeps its day, nothing follows until Veroia.
SELECT CASE WHEN md5(pg_get_viewdef('public.v_vs_state'::regclass, true)) = '041915cfb57a58b09f29e5232232d515' THEN '097 in place' ELSE '097 NOT APPLIED' END AS applied,
       (SELECT count(*) FROM public.v_vs_state) AS vs_orders,
       (SELECT count(*) FROM public.v_piece_state ps
      JOIN public.piece_legs l ON l.piece_id = ps.piece_id AND l.deleted_at IS NULL
      JOIN public.rt_stops pk ON pk.id = l.pickup_stop_id
      JOIN public.rt_stops dr ON dr.id = l.drop_stop_id
      LEFT JOIN public.locations hub ON hub.is_hub
     WHERE (ps.kind = 'vs_import' AND pk.location_id IS DISTINCT FROM hub.id)
        OR (ps.kind = 'vs_export' AND dr.location_id IS DISTINCT FROM hub.id)) AS vs_legs_off_veroia,
       (SELECT count(*) FROM public.v_vs_state v WHERE v.first_hub_day IS NULL AND v.carriers <> '[]'::jsonb) AS vs_carried_no_veroia_day,
       (SELECT count(*) FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace ns ON ns.oid = c.relnamespace
      WHERE NOT t.tgisinternal AND t.tgenabled <> 'D' AND ns.nspname = 'public') = (SELECT red_value FROM monitoring.checks WHERE id = 'B-54') AS b54_matches;
